import { CitationPanel } from './CitationPanel'
@Component
export struct EntryTile {
  @Prop body: string = ''
  @Prop citation: string = ''
  build() {
    Column() {
      Text(this.body).fontSize(18)
      CitationPanel({ text: this.citation })
    }
  }
}

